        :root{--pink:#d8417d;--rose:#fff1f6;--ink:#302a32;--muted:#837981;--line:#eee4e8;--green:#16785b;--amber:#a36a16}*{box-sizing:border-box}body{margin:0;background:#fcfafb;color:var(--ink);font:14px 'DM Sans',sans-serif}.page{max-width:930px;margin:auto;padding:36px 24px 70px}.back{display:inline-block;color:#b82d67;text-decoration:none;font-weight:700;font-size:13px;margin-bottom:22px}.head{border-bottom:1px solid var(--line);padding-bottom:24px;margin-bottom:28px}.eyebrow{font-size:10px;color:var(--pink);font-weight:700;letter-spacing:1.3px}.head h1{font:700 31px 'Playfair Display',serif;margin:5px 0}.head p{color:var(--muted);margin:0}.form-card{background:#fff;border:1px solid var(--line);border-radius:18px;padding:28px;box-shadow:0 12px 35px #5e293609}.section{padding:3px 0 25px;margin-bottom:23px;border-bottom:1px solid #f5eef1}.section:last-of-type{border:0;margin:0;padding-bottom:0}.section-title{font-size:11px;color:#aa9ca3;letter-spacing:1.1px;font-weight:700;margin-bottom:13px}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:15px}.field{display:flex;flex-direction:column;gap:7px}.field label{font-size:12px;font-weight:700}.field label span{font-weight:400;color:var(--muted)}input,select,textarea{width:100%;border:1px solid #e6d9df;border-radius:9px;padding:11px 12px;background:#fff;color:var(--ink);font:inherit;outline:0}input:focus,select:focus,textarea:focus{border-color:#dc6e9a;box-shadow:0 0 0 3px #fce7ef}textarea{resize:vertical;min-height:92px}.client-search{margin-bottom:11px}.client-card{display:none;background:var(--rose);border:1px solid #f5d8e5;border-radius:10px;padding:13px 14px;margin-top:12px}.client-card.show{display:block}.client-card b{display:block;margin-bottom:4px}.client-card small{color:var(--muted)}.treatment-summary{display:none;align-items:center;gap:10px;margin-top:14px;background:#fbf8f9;border-radius:10px;padding:12px}.treatment-summary.show{display:flex}.treatment-summary strong{font-size:13px}.treatment-summary span{font-size:12px;color:var(--muted)}.availability{border-radius:10px;padding:11px 13px;margin-top:14px;background:#f7f4f5;color:var(--muted);font-size:13px}.availability.available{background:#e8f7f1;color:var(--green)}.availability.unavailable{background:#fff2e9;color:var(--amber)}.help{font-size:11px;color:var(--muted);margin:7px 0 0}.toggle{display:flex;align-items:center;gap:9px;font-weight:600}.toggle input,.channels input{width:auto;accent-color:var(--pink)}.channels{display:flex;gap:17px;margin:12px 0 0 25px;color:var(--muted);font-size:13px}.channels.disabled{opacity:.42;pointer-events:none}.error{background:#fff0f2;color:#bc315d;border-radius:9px;padding:11px 13px;margin-bottom:20px}.field-error{font-size:11px;color:#c23461}.actions{display:flex;justify-content:flex-end;gap:11px;padding-top:25px;margin-top:24px;border-top:1px solid var(--line)}.button{border:1px solid var(--line);border-radius:9px;padding:11px 16px;background:#fff;text-decoration:none;color:#635861;font:600 13px 'DM Sans';cursor:pointer}.button.primary{background:var(--pink);border-color:var(--pink);color:#fff;box-shadow:0 7px 17px #d8417d3b}@media(max-width:620px){.page{padding:24px 15px}.form-card{padding:20px}.field-grid{grid-template-columns:1fr}.head h1{font-size:27px}.actions{flex-direction:column-reverse}.button{text-align:center}}
    </style>
</head>
