        <section class="section">
            <div class="section-title">👤 CLIENTE</div>
            <input class="client-search" type="search" id="patient-search" placeholder="Buscar por nombre, documento o teléfono" autocomplete="off">
            <div class="field"><label for="patient_id">Cliente seleccionado</label><select id="patient_id" name="patient_id" required><option value="">Selecciona un cliente</option>@foreach($patients as $patient)<option value="{{ $patient->id }}" data-document="{{ $patient->document_type }} {{ $patient->document_number }}" data-phone="{{ $patient->phone }}" data-completed="{{ $patient->completed_appointments_count }}" data-pending="{{ $patient->pending_appointments_count }}" data-cancelled="{{ $patient->cancelled_appointments_count }}" @selected(old('patient_id') == $patient->id)>{{ $patient->first_name }} {{ $patient->last_name }} — {{ $patient->document_number }}</option>@endforeach</select>@error('patient_id')<span class="field-error">{{ $message }}</span>@enderror</div>
