            <div class="field-grid"><div class="field"><label for="treatment_catalog_id">Tratamiento</label><select id="treatment_catalog_id" name="treatment_catalog_id" required><option value="">Selecciona un tratamiento</option>@foreach($treatments as $treatment)<option value="{{ $treatment->id }}" data-duration="{{ $treatment->duration_minutes }}" data-sanitization="{{ $treatment->sanitization_minutes }}" data-price="{{ $treatment->base_price }}" @selected(old('treatment_catalog_id') == $treatment->id)>{{ $treatment->name }}</option>@endforeach</select></div><div class="field"><label for="user_id">Profesional</label><select id="user_id" name="user_id" required><option value="">Selecciona un profesional</option>@foreach($specialists as $specialist)<option value="{{ $specialist->id }}" @selected(old('user_id') == $specialist->id)>{{ $specialist->name }}</option>@endforeach</select></div></div>
