        <section class="section"><div class="section-title">🔔 RECORDATORIO</div><input type="hidden" name="send_reminder" value="0"><label class="toggle"><input id="send-reminder" type="checkbox" name="send_reminder" value="1" @checked(old('send_reminder'))> Enviar recordatorio al cliente</label><div class="channels {{ old('send_reminder') ? '' : 'disabled' }}" id="channels"><label><input type="checkbox" name="reminder_channels[]" value="whatsapp" @checked(in_array('whatsapp', old('reminder_channels', ['whatsapp'])))> WhatsApp</label><label><input type="checkbox" name="reminder_channels[]" value="email" @checked(in_array('email', old('reminder_channels', [])))> Correo</label></div><p class="help">Se envían recordatorios programados 24 y 2 horas antes de la cita.</p></section>
        <div class="actions"><a class="button" href="{{ route('agenda.index') }}">Cancelar</a><button class="button primary" type="submit">✓ Crear cita</button></div>
