</main>
<script>
    const treatment = document.querySelector('#treatment_catalog_id'), professional = document.querySelector('#user_id'), box = document.querySelector('#box_id'), date = document.querySelector('#appointment-date'), time = document.querySelector('#appointment-time'), startsAt = document.querySelector('#starts_at'), price = document.querySelector('#price'), availability = document.querySelector('#availability');
    const option = (select) => select.options[select.selectedIndex];
    function updateClient(){const selected=option(document.querySelector('#patient_id')), card=document.querySelector('#client-card');if(!selected.value){card.classList.remove('show');return}document.querySelector('#client-name').textContent=selected.textContent.split(' — ')[0];document.querySelector('#client-info').textContent=`${selected.dataset.document} · ${selected.dataset.phone}`;document.querySelector('#client-history').textContent=`Historial: ${selected.dataset.completed} completadas · ${selected.dataset.pending} activas · ${selected.dataset.cancelled} canceladas`;card.classList.add('show')}
    document.querySelector('#patient_id').addEventListener('change',updateClient); document.querySelector('#patient-search').addEventListener('input',e=>{const term=e.target.value.toLowerCase();[...document.querySelector('#patient_id').options].forEach((item,i)=>item.hidden=i>0&&!item.textContent.toLowerCase().includes(term))}); updateClient();
    function updateTreatment(){const selected=option(treatment), summary=document.querySelector('#treatment-summary'); if(!selected.value){summary.classList.remove('show');return}const total=Number(selected.dataset.duration)+Number(selected.dataset.sanitization);document.querySelector('#duration-text').textContent=`Duración estimada: ${selected.dataset.duration} minutos${Number(selected.dataset.sanitization)?` + ${selected.dataset.sanitization} min de preparación`:''}`;document.querySelector('#price-text').textContent=` · Precio base: $${Number(selected.dataset.price).toLocaleString('es-CO')}`;if(!price.value)price.value=selected.dataset.price;summary.classList.add('show');[...box.options].forEach((item,i)=>{if(!i)return;item.hidden=!item.dataset.treatments.split(',').includes(selected.value)});if(option(box).hidden)box.value='';loadSlots()}
    async function loadSlots(){startsAt.value='';time.innerHTML='<option value="">Consultando disponibilidad…</option>';time.disabled=true;const valid=treatment.value&&professional.value&&box.value&&date.value;if(!valid){availability.className='availability';availability.textContent='Selecciona el tratamiento, profesional, box y fecha para consultar los horarios.';time.innerHTML='<option value="">Completa los campos anteriores</option>';return}const params=new URLSearchParams({treatment_catalog_id:treatment.value,user_id:professional.value,box_id:box.value,date:date.value});try{const response=await fetch(`{{ route('agenda.availability') }}?${params}`),data=await response.json();time.innerHTML='<option value="">Selecciona una hora disponible</option>'+data.slots.map(slot=>`<option value="${slot}">${new Date(`2000-01-01T${slot}`).toLocaleTimeString('es-CO',{hour:'numeric',minute:'2-digit'})}</option>`).join('');time.disabled=!data.slots.length;availability.className=`availability ${data.slots.length?'available':'unavailable'}`;availability.textContent=data.slots.length?'● Horarios disponibles. El sistema validará nuevamente al crear la cita.':'No hay horarios disponibles con esta combinación.'}catch(error){availability.className='availability unavailable';availability.textContent='No fue posible consultar la disponibilidad. Intenta de nuevo.';time.innerHTML='<option value="">Sin disponibilidad</option>'}}
    [treatment,professional,box,date].forEach(input=>input.addEventListener('change',input===treatment?updateTreatment:loadSlots));time.addEventListener('change',()=>startsAt.value=time.value?`${date.value} ${time.value}`:'');document.querySelector('#send-reminder').addEventListener('change',e=>document.querySelector('#channels').classList.toggle('disabled',!e.target.checked)); if(treatment.value)updateTreatment();
</script>
</body></html>
